import java.io.*;import java.nio.file.*;import java.util.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.baksmali.*;import com.android.tools.smali.baksmali.Adaptors.*;import com.android.tools.smali.baksmali.formatter.*;
public class InspectApk{public static void main(String[]args)throws Exception{var wanted=Set.of("Lcom/facebook/react/internal/featureflags/ReactNativeFeatureFlagsDefaults;","Lcom/facebook/react/runtime/ReactHostImpl;","Lcom/facebook/react/runtime/ReactSurfaceImpl;","Lcom/facebook/react/modules/deviceinfo/DeviceInfoModule;","Lcom/usgreekscan/zoi/MainActivity;","Lcom/usgreekscan/zoi/MainApplication;");var container=DexFileFactory.loadDexContainer(new File(args[0]),Opcodes.getDefault());for(String entry:container.getDexEntryNames()){for(var type:container.getEntry(entry).getDexFile().getClasses()){if(wanted.contains(type.getType())){String shortName=type.getType().substring(type.getType().lastIndexOf('/')+1,type.getType().length()-1);try(var writer=Files.newBufferedWriter(Path.of(args[1],shortName+".smali"))){new ClassDefinition(new BaksmaliOptions(),type).writeTo(new BaksmaliWriter(writer));}System.out.println(entry+" "+type.getType());}}}}}
